const block=(id,title,html)=>[id,title,html];
export const choosingDepth=[
 block('situations','Какая задача у ваших будущих очков?',`<div class="guide-scenarios"><a href="#screen"><strong>Работаю за компьютером</strong><span>Расстояние до монитора, рабочая зона и покрытия ↗</span></a><a href="/lenses/progressivnye-linzy"><strong>Меняю очки для дали и чтения</strong><span>Прогрессивные и офисные конструкции ↗</span></a><a href="#sun"><strong>Хочу комфорт на солнце</strong><span>Фотохром, тонировка и поляризация ↗</span></a><a href="#driving"><strong>Много времени за рулём</strong><span>Дневные блики и зрение в сумерках ↗</span></a><a href="#children"><strong>Выбираю очки ребёнку</strong><span>Посадка, материал и наблюдение ↗</span></a><a href="#indices"><strong>Хочу тонкие и аккуратные линзы</strong><span>Индекс, размер оправы и форма поверхности ↗</span></a></div><p>Это ориентиры для разговора со специалистом. У одной пары может быть несколько свойств: например, прогрессивная конструкция и фотохромный материал.</p>`),
 block('indices','Индексы 1,50–1,74: что означают цифры?',`<p>Индекс преломления описывает оптическое свойство материала. При сопоставимых условиях более высокий индекс позволяет уменьшить толщину линзы. Он не обозначает диоптрии и не является оценкой качества.</p><div class="guide-table-wrap"><table class="guide-table"><caption>Общие ориентиры для обсуждения материала</caption><thead><tr><th scope="col">Индекс</th><th scope="col">Что обсудить</th></tr></thead><tbody><tr><th scope="row">1,50</th><td>Базовый вариант органических линз. Сравните расчёт толщины в выбранной оправе.</td></tr><tr><th scope="row">1,53 / 1,59</th><td>Встречаются у материалов Trivex и поликарбонат соответственно. Материал оценивают также по ударостойкости, весу и оптическим свойствам.</td></tr><tr><th scope="row">1,60</th><td>Один из вариантов уменьшения толщины. Польза зависит от рецепта и размера линзы.</td></tr><tr><th scope="row">1,67 / 1,74</th><td>Высокоиндексные материалы. Обсудите расчёт толщины, покрытия и разницу в стоимости.</td></tr></tbody></table></div><p>Нет универсального правила «при таких диоптриях нужен только такой индекс». Сравнивать нужно готовую линзу с учётом рецепта и оправы. Для минусовых линз особенно заметна толщина края; для плюсовых — центра.</p>`),
 block('surface','Сферические и асферические: в чём разница?',`<p>Сферическая поверхность имеет форму участка сферы. У асферической кривизна изменяется от центра к краям. Это позволяет оптимизировать профиль и оптические свойства линзы; результат зависит от рецепта и конкретной конструкции.</p><div class="guide-comparison"><div><h3>Сферическая</h3><p>Распространённая конструкция. Оцените внешний вид, толщину и комфорт в выбранной оправе.</p></div><div><h3>Асферическая</h3><p>Может иметь более плоский профиль. Особенно важно правильно выполнить центровку и подобрать посадку.</p></div><div><h3>Индивидуальная</h3><p>При изготовлении могут учитываться дополнительные параметры посадки. Уточните, какие именно измерения использует выбранная линза.</p></div></div><p>Индекс материала и форма поверхности — разные характеристики. «Асферическая» не означает автоматически «самая тонкая» или «подходит всем».</p>`),
 block('screen','Линзы для компьютера: начните с расстояния',`<p>Запишите, где стоят экран и клавиатура, измерьте расстояние от глаз до монитора. Очки для чтения на близком расстоянии не всегда удобны для более удалённого экрана.</p><ul><li>Для одной рабочей дистанции можно обсудить однофокальную коррекцию.</li><li>Для монитора, документов и общения в помещении — офисную конструкцию с нужным диапазоном.</li><li>Для переключения между работой и далью — прогрессивные линзы; сравните удобство их средней зоны.</li></ul><details><summary>Нужен ли обязательно фильтр синего света?</summary><p>Он не заменяет правильно подобранную коррекцию, перерывы и удобное рабочее место. Американская академия офтальмологии не рекомендует специальные очки только ради защиты от света экрана: повреждение глаз обычным использованием экранов не доказано.</p><p>Если ощущаете сухость, головную боль или устойчивое размытие, обсудите симптомы со специалистом, а не выбирайте покрытие как лечение.</p></details>`),
 block('sun','Солнце: фотохром, тонировка или поляризация?',`<div class="guide-table-wrap"><table class="guide-table"><caption>Три разных свойства линз</caption><thead><tr><th scope="col">Вариант</th><th scope="col">Что даёт</th><th scope="col">Что уточнить</th></tr></thead><tbody><tr><th scope="row">Фотохром</th><td>Меняет степень затемнения при изменении условий освещения.</td><td>Скорость осветления, остаточный оттенок, реакцию на температуру и работу за стеклом автомобиля.</td></tr><tr><th scope="row">Постоянная тонировка</th><td>Имеет заданный цвет и степень затемнения.</td><td>УФ-защиту и допустимость использования в ваших условиях. Тёмная линза неудобна в помещении.</td></tr><tr><th scope="row">Поляризация</th><td>Уменьшает некоторые отражённые блики, например от воды или дороги.</td><td>Видимость экранов и приборов через выбранные линзы. Это отдельное свойство, а не синоним фотохрома.</td></tr></tbody></table></div><p>Затемнение и УФ-защита — разные характеристики. Проверяйте данные конкретного изделия. У некоторых фотохромных серий предусмотрена работа в автомобиле; такую способность нельзя приписывать всем «хамелеонам».</p>`),
 block('driving','Очки для вождения: день и сумерки — разные задачи',`<p>Днём полезно обсудить солнцезащитный вариант и отражённые блики. В сумерках важны актуальная коррекция, чистые линзы и покрытия, уменьшающие отражения на их поверхности. Дневные тёмные очки не подходят для ночной поездки.</p><p>Если встречные фары стали заметно мешать или ухудшилось зрение в темноте, начните с проверки зрения. Название «для водителей» не означает, что линза устранит любой источник ослепления.</p><p>При примерке проверьте чтение приборной панели, обзор дороги и посадку. Для прогрессивной пары дополнительно обсудите размеры зон и опыт ношения.</p>`),
 block('children','Линзы ребёнку: коррекция и контроль миопии',`<p>При детских очках важно учитывать рецепт, устойчивую посадку оправы и условия использования. Специалист подбирает материал с учётом возраста и активности; ударостойкость не означает, что линза не может повредиться.</p><p>Линзы для контроля миопии — отдельная категория, а не обычные очки с дополнительным покрытием. Возможность их назначения и план наблюдения обсуждают с офтальмологом. Нельзя обещать остановку снижения зрения каждому ребёнку.</p><p>На консультацию возьмите прежние рецепты и сведения о наблюдении. Уточните, как часто проверять зрение и посадку очков по индивидуальному плану.</p>`),
 block('budget','Из чего складывается стоимость линз?',`<p>Цена зависит от конструкции, материала, покрытий, индивидуальных параметров и сложности изготовления. Сравнивать две пары только по бренду или индексу недостаточно.</p><ol><li>Попросите записать полное название линзы и покрытия.</li><li>Уточните, какие измерения входят в подбор.</li><li>Сравните варианты под одну и ту же оправу и рецепт.</li><li>Проверьте, включает ли сумма обе линзы, установку и оправу.</li><li>Уточните сроки изготовления, условия проверки готовых очков и обращения при дискомфорте.</li></ol><p>Точную стоимость можно определить после выбора параметров; одинаковое название категории не гарантирует одинаковое изделие.</p>`),
 block('mistakes','Пять ошибок при выборе линз',`<ol><li><strong>Выбирать по старым диоптриям без обсуждения изменений зрения.</strong> Актуальность коррекции влияет на комфорт сильнее рекламного названия покрытия.</li><li><strong>Заказывать самый высокий индекс «на всякий случай».</strong> Сначала сравните расчёт толщины и стоимость на своей оправе.</li><li><strong>Ждать одинакового удобства от одних очков во всех условиях.</strong> Рабочее место, улица и вождение могут требовать разных решений.</li><li><strong>Путать УФ-защиту, поляризацию и тёмный цвет.</strong> Они решают разные задачи.</li><li><strong>Терпеть сохраняющийся дискомфорт без проверки.</strong> Посадку, центровку и параметры готовой пары нужно оценить со специалистом.</li></ol>`),
 block('references','Источники и дополнительное чтение',`<ul class="guide-references"><li><a href="https://www.zeiss.com/vision-care/en/eye-health-and-care/understanding-vision/plastic-or-glass-lenses.html" target="_blank" rel="noopener">ZEISS: материалы очковых линз</a></li><li><a href="https://www.zeiss.com/vision-care/us/eye-care-professionals/lenses/lenses-for-every-need/single-vision-aspheric.html" target="_blank" rel="noopener">ZEISS: асферические линзы</a></li><li><a href="https://www.hoyavision.com/vision-products/photochromic-lenses/" target="_blank" rel="noopener">HOYA: фотохромные конструкции</a></li><li><a href="https://aao.org/eye-health/tips-prevention/are-computer-glasses-worth-it" target="_blank" rel="noopener">AAO: очки и свет цифровых экранов</a></li></ul><p>Материал объясняет принципы выбора. Наличие конкретных серий, цены и условия изготовления уточняются в салоне.</p>`)
];
export const progressiveDepth=[
 block('day','Как пользоваться зонами в течение дня',`<div class="guide-scenarios"><div><strong>Прогулка и дорога</strong><span>Смотрите через верхнюю зону для дали.</span></div><div><strong>Экран на рабочем столе</strong><span>Средняя дистанция находится в переходной зоне. Высоту экрана и посадку обсуждают при подборе.</span></div><div><strong>Книга или телефон</strong><span>Используется нижняя зона для близи. Привычное положение головы может измениться.</span></div></div><p>Это общая схема использования, а не инструкция по индивидуальной посадке. Специалист покажет, как найти зоны именно в вашей паре.</p>`),
 block('tradeoffs','Почему есть боковые искажения и узкая рабочая зона?',`<p>Плавное изменение оптической силы связано с особенностями боковых областей линзы. При взгляде в сторону изображение может отличаться от привычного. Поэтому движение головы к объекту помогает использовать нужную зону.</p><p>Ширина удобных зон и переходы различаются у конструкций. Более индивидуальное изготовление не отменяет физические особенности прогрессивной линзы и не гарантирует мгновенного привыкания.</p><p>Если вы много часов смотрите на широкий монитор, сравните прогрессивную пару с отдельными офисными очками. Оценивать нужно вашу задачу, а не только уровень линзы в каталоге.</p>`),
 block('frame','Почему оправа и измерения так важны?',`<p>Высота оправы должна позволять разместить необходимые зоны выбранной конструкции. Слишком низкая оправа может ограничить выбор; её совместимость проверяют до заказа.</p><p>При измерениях учитывают положение глаз и высоту установки линз. Для некоторых индивидуальных конструкций нужны также параметры расстояния до глаз, наклона и изгиба оправы. Какие данные используются, зависит от конкретной линзы.</p><p>Если готовые очки сползают, зоны смещаются относительно взгляда. Регулировка посадки — часть проверки удобства, а не повод самостоятельно сгибать оправу.</p>`),
 block('first-days','Первые дни: практический план',`<ol><li>При выдаче попросите показать зоны на знакомых объектах: текст, экран и объект вдали.</li><li>Начните использовать очки в спокойной обстановке и следуйте рекомендациям специалиста.</li><li>На лестницах и бордюрах уделяйте внимание направлению взгляда.</li><li>Перед вождением убедитесь, что уверенно ориентируетесь и видите нужные расстояния.</li><li>Запишите, в какой ситуации неудобно: чтение, экран, даль или боковой взгляд. С этой информацией проще проверить пару.</li></ol><p>Нет одинакового для всех срока адаптации. Если симптомы выражены или сохраняются, обращайтесь за проверкой, а не пытайтесь привыкать любой ценой.</p>`),
 block('order','Что уточнить перед заказом прогрессивных очков',`<ul><li>Полное название конструкции и какие параметры индивидуализируются.</li><li>Совместимость с выбранной оправой и привычной посадкой.</li><li>Ожидаемое удобство именно на вашем рабочем месте.</li><li>Отличия предложенных вариантов: зоны, материал, покрытия и итоговая цена.</li><li>Когда будет проверка готовой пары и как обратиться, если она неудобна.</li><li>Условия салона при повторной проверке и возможной замене. Их нужно подтвердить до оплаты.</li></ul><p>Возьмите прежние очки и рецепты. Если есть опыт прогрессивных линз, расскажите, что в них нравилось и что мешало.</p>`)
];
export function extendGuidePages(pages){
 const choose=pages['/lenses/kak-vybrat-linzy'];
 choose.sections.splice(1,0,choosingDepth[0]);
 choose.sections.splice(4,0,...choosingDepth.slice(1,3));
 const position=choose.sections.findIndex(s=>s[0]==='consultation');
 choose.sections.splice(position,0,...choosingDepth.slice(3,8));
 choose.sections.splice(choose.sections.findIndex(s=>s[0]==='questions'),0,choosingDepth[8]);
 choose.sections.push(choosingDepth[9]);
 const progressive=pages['/lenses/progressivnye-linzy'];
 progressive.sections.splice(1,0,progressiveDepth[0]);
 progressive.sections.splice(progressive.sections.findIndex(s=>s[0]==='adaptation'),0,progressiveDepth[1],progressiveDepth[2]);
 progressive.sections.splice(progressive.sections.findIndex(s=>s[0]==='comparison'),0,progressiveDepth[3],progressiveDepth[4]);
}
